package org.simpleweather.app;

import android.app.*;
import android.content.*;
import android.os.Build;
import java.time.*;

/** Local timetable notifications based on the saved timetable and device calendar. */
final class ScheduleNotifier {
    private static final String CHANNEL="course_reminders_v1";private static final int ALARM=230001,NOTE=230002;
    private static PendingIntent alarm(Context c){return PendingIntent.getBroadcast(c,ALARM,new Intent(c,TodoReceiver.class).setAction("course.tick"),PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);}
    static void receive(Context context,Intent intent){refresh(context,true);}
    static synchronized void refresh(Context original,boolean dispatch){Context c=original.getApplicationContext();AlarmManager am=c.getSystemService(AlarmManager.class);am.cancel(alarm(c));NotificationManager nm=c.getSystemService(NotificationManager.class);nm.cancel("course",NOTE);if(!c.getSharedPreferences("toolbox",0).getBoolean("course_notify",true))return;if(Build.VERSION.SDK_INT>=26){NotificationChannel ch=new NotificationChannel(CHANNEL,c.getString(R.string.course_notify_channel),NotificationManager.IMPORTANCE_HIGH);ch.setDescription(c.getString(R.string.course_notify_channel_note));nm.createNotificationChannel(ch);}ScheduleModel m;try{String raw=c.getSharedPreferences("timetable",0).getString("data","");m=raw.isEmpty()?new ScheduleModel():ScheduleModel.parse(raw);}catch(Exception e){return;}long now=System.currentTimeMillis();ZoneId z=ZoneId.systemDefault();int lead=c.getSharedPreferences("toolbox",0).getInt("course_notify_lead",30),remove=c.getSharedPreferences("toolbox",0).getInt("course_notify_remove",10);long next=Long.MAX_VALUE,activeStart=Long.MAX_VALUE;ScheduleModel.Course active=null;for(int d=0;d<14;d++){LocalDate day=LocalDate.now(z).plusDays(d);int week=m.week(day);if(week<1||week>m.weeks)continue;for(ScheduleModel.Course course:m.courses)if(course.day==day.getDayOfWeek().getValue()&&course.runs(week)){long start=day.atTime(LocalTime.parse(m.slots.get(course.first-1).start)).atZone(z).toInstant().toEpochMilli(),show=start-lead*60000L,hide=start+remove*60000L;if(now>=show&&now<hide&&(active==null||start<activeStart)){active=course;activeStart=start;}if(show>now)next=Math.min(next,show);if(hide>now)next=Math.min(next,hide);}}if(active!=null&&dispatch&&allowed(c)){long remaining=Math.max(0,activeStart-now);String body=remaining==0?c.getString(R.string.course_notify_started):c.getString(R.string.course_notify_in,Math.max(1,(remaining+59999)/60000));Notification.Builder b=Build.VERSION.SDK_INT>=26?new Notification.Builder(c,CHANNEL):new Notification.Builder(c);b.setSmallIcon(android.R.drawable.ic_menu_agenda).setContentTitle(active.name).setContentText(body).setStyle(new Notification.BigTextStyle().bigText(body)).setContentIntent(PendingIntent.getActivity(c,231,new Intent(c,MainActivity.class).putExtra("last_tab",1),PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE)).setAutoCancel(false).setOngoing(true);try{nm.notify("course",NOTE,b.build());}catch(SecurityException ignored){}}if(next!=Long.MAX_VALUE){try{if(Build.VERSION.SDK_INT>=23)am.setExactAndAllowWhileIdle(AlarmManager.RTC_WAKEUP,next,alarm(c));else am.setExact(AlarmManager.RTC_WAKEUP,next,alarm(c));}catch(SecurityException e){am.set(AlarmManager.RTC_WAKEUP,next,alarm(c));}}}
    private static boolean allowed(Context c){return Build.VERSION.SDK_INT<33||(c.checkSelfPermission(android.Manifest.permission.POST_NOTIFICATIONS)==android.content.pm.PackageManager.PERMISSION_GRANTED&&c.getSystemService(NotificationManager.class).areNotificationsEnabled());}
}
